package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;import com.fasterxml.jackson.databind.node.ObjectNode;import com.ruoyi.medical.contracts.*;
import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;
class BuiltinEvaluationPlanningContextCompilerTest {
 final PermissionSchema json=new PermissionSchema();final SchemaCatalogue catalogue=SchemaCatalogue.fromProject(Path.of(System.getProperty("medical.projectRoot","/tmp/stage22-task-runtime/n-evaluation-context-materialization/catalogue-root")));final BuiltinEvaluationPlanningContextCompiler compiler=new BuiltinEvaluationPlanningContextCompiler(catalogue,json);
 BuiltinEvaluationPlanningContextCompilerTest()throws Exception{}
 static String id(int i){return "00000000-0000-4000-8000-"+String.format("%012d",i);}static String hash(String s){return org.apache.commons.codec.digest.DigestUtils.sha256Hex(s);}
 PermissionProtocol.Basis basis(int i){return new PermissionProtocol.Basis(id(i),hash("v"+i));}
 FormalEvaluationContextProtocol.Node binding(){return new FormalEvaluationContextProtocol.Node("N01",basis(1),basis(2),basis(3),new FormalEvaluationContextProtocol.Schema(BuiltinEvaluationPlanningContextCompiler.INPUT,catalogue.schemaDigest("evaluation-planning-context-compiler")),new FormalEvaluationContextProtocol.Schema(BuiltinEvaluationPlanningContextCompiler.OUTPUT,catalogue.schemaDigest("simulation-execution")));}
 ObjectNode doc(){var d=json.object().put("schema_version","1.0.0").put("document_type","PRODUCT_TECHNICAL_REQUIREMENTS").put("language","zh-CN");d.putArray("sections").addObject().put("section_id","1").put("title","原题 😀").put("text","原件严格数值 1.00 mm\né，不作改写");return d;}
 ObjectNode prompt(){var p=json.object().put("schema_version","1.0.0");p.putArray("system_messages").add("原文系统规则\n  空白不改").add("不推断未知事实");return p;}
 ObjectNode tool()throws Exception{var p=json.object().put("schema_version","1.0.0").put("kind","EVALUATION_CONTEXT_ASSEMBLER").put("implementation_id",BuiltinEvaluationPlanningContextCompiler.IMPLEMENTATION).put("implementation_version","1.0.0").put("implementation_class_sha256",compiler.implementationClassSha256()).put("context_mode","N01_PLANNING").put("tool_mode","NONE").put("upstream_mode","ORIGINAL_PLAN_PREPARATION");for(var e:Map.of("input_schema",BuiltinEvaluationPlanningContextCompiler.INPUT,"output_schema",BuiltinEvaluationPlanningContextCompiler.OUTPUT,"prompt_package_schema",BuiltinEvaluationPlanningContextCompiler.PROMPT).entrySet())p.putObject(e.getKey()).put("schema_ref",e.getValue()).put("schema_sha256",catalogue.schemaDigest(e.getKey().equals("output_schema")?"simulation-execution":"evaluation-planning-context-compiler"));return p;}
 ObjectNode planning()throws Exception {
  var p=json.object();p.set("template",json.tree(basis(30)));p.put("profile_revision",id(31)).put("profile_sha256",hash("profile"));p.putArray("profile_attributes");
  var template=p.putObject("template_content").put("schema_version","1.0.0").put("document_type","PRODUCT_TECHNICAL_REQUIREMENTS").put("application_path","FIRST_REGISTRATION").put("ivd",false);template.putNull("directory_profile");
  var node=template.putArray("nodes").addObject().put("node_id",id(60)).putNull("parent_id").put("official_number","1").put("title","Original template title").put("ordinal",1).put("required",true).put("content_mode","NARRATIVE").put("nature","OFFICIAL");
  var condition=json.object().put("mode","ALWAYS").putNull("rule_revision").putNull("engine_revision");condition.putArray("input_keys");node.set("condition",condition);node.putArray("basis_refs");node.putArray("content_requirements");
  var rule=node.putObject("evidence_rule").put("mode","NARRATIVE").putNull("calculation_rule_revision").put("require_original_locator",true).put("require_human_verification",true);rule.putArray("authority_source_types");rule.putArray("verification_rule_revisions");rule.putArray("input_field_ids");
  for(String k:List.of("field_definitions","repeat_definitions","attachment_requirements","cross_document_rules"))template.putArray(k);
  var conditions=template.putObject("condition_schema").put("unknown_result","UNKNOWN");conditions.putArray("attribute_keys");conditions.set("applicability",condition);template.putArray("basis_manifest").add(json.tree(basis(70)));
  var format=template.putObject("format_profile").put("attachment_order","DECLARED_ORDINAL");format.set("format_revision",json.tree(basis(71)));format.set("numbering_rule_revision",json.tree(basis(72)));format.putArray("output_types").add("DOCX");format.putArray("font_artifacts").add(json.tree(basis(73)));format.putArray("node_displays");
  var plan=new ArtifactProtocol.PlanCandidate(id(30),id(31),List.of(id(60)),List.of(new ArtifactProtocol.PlanSection(id(61),List.of(id(60)),"Original template title",null,ArtifactProtocol.Method.HUMAN_PROVIDED,List.of(),List.of())),List.of(),List.of(id(60)));
  p.set("plan_candidate",json.tree(plan));p.putArray("conditions").addObject().put("scope","NODE").put("target_id",id(60)).putNull("rule_revision").putNull("engine_revision").put("status","UNKNOWN").putArray("input_keys");((ObjectNode)p.path("conditions").get(0)).putArray("unknown_input_keys");
  p.putArray("blockers").addObject().put("code","OWNER_UNASSIGNED").putArray("target_ids").add(id(61));return p;
 }
 @Test void oldDocumentPackageCannotBeUpgraded()throws Exception{var t=tool().put("context_mode","DOCUMENT_ONLY");assertThrows(SchemaRejection.class,()->run(t,prompt(),doc()));}
 @Test void unknownOwnersRulesAndConditionsSurviveCompilation()throws Exception{var output=new com.fasterxml.jackson.databind.ObjectMapper().readTree(run(tool(),prompt(),doc()).bytes());var body=new com.fasterxml.jackson.databind.ObjectMapper().readTree(output.required("messages").get(2).required("content").asText());assertEquals(planning(),body.required("planning"));assertTrue(body.path("planning").path("plan_candidate").path("sections").get(0).path("owner_id").isNull());assertFalse(body.has("expected_ref"));}
 byte[] bytes(JsonNode n)throws Exception{return json.canonical(n).getBytes(StandardCharsets.UTF_8);}
 BuiltinEvaluationPlanningContextCompiler.Compilation run(ObjectNode t,ObjectNode p,JsonNode d)throws Exception{return compiler.compile(bytes(t),bytes(p),d,planning(),binding());}
 @Test void actualRegisteredSchemasCompileOriginalTextWithoutInference()throws Exception{var d=doc();var p=prompt();var result=run(tool(),p,d);var out=new com.fasterxml.jackson.databind.ObjectMapper().readTree(result.bytes());assertEquals(3,out.path("messages").size());assertEquals(p.path("system_messages").get(0),out.path("messages").get(0).path("content"));assertEquals(p.path("system_messages").get(1),out.path("messages").get(1).path("content"));assertEquals(json.canonical(json.object().setAll(Map.of("document",d,"planning",planning()))),out.path("messages").get(2).path("content").asText());assertTrue(out.path("tools").isEmpty());assertEquals(2,out.size());assertEquals(compiler.implementationClassSha256(),result.implementationSha256());catalogue.validate("simulation-execution",out,"ExactInput");}
 @Test void deterministicAndDefensiveCopies()throws Exception{var t=tool();var p=prompt();var d=doc();var a=run(t,p,d);var b=run(t,p,d);assertArrayEquals(a.bytes(),b.bytes());assertEquals(a.inputSha256(),b.inputSha256());byte[] copy=a.bytes();copy[0]=0;assertArrayEquals(a.bytes(),b.bytes());d.put("language","en");assertArrayEquals(a.bytes(),b.bytes());}
 @Test void actualCompilerClassHashMatchesResourceBytes()throws Exception{try(var in=BuiltinEvaluationPlanningContextCompiler.class.getResourceAsStream("BuiltinEvaluationPlanningContextCompiler.class")){assertEquals(org.apache.commons.codec.digest.DigestUtils.sha256Hex(in.readAllBytes()),compiler.implementationClassSha256());}}
 @Test void classDigestCannotBeDeclaredByCaller()throws Exception{assertThrows(TenantAccessException.class,()->run(tool().put("implementation_class_sha256",hash("fake")),prompt(),doc()));}
 @Test void implementationVersionCannotFallback()throws Exception{assertThrows(SchemaRejection.class,()->run(tool().put("implementation_version","2.0.0"),prompt(),doc()));}
 @Test void arbitraryImplementationCannotRun()throws Exception{assertThrows(SchemaRejection.class,()->run(tool().put("implementation_id","/bin/sh"),prompt(),doc()));}
 @Test void arbitraryExecutablePropertyRejected()throws Exception{assertThrows(SchemaRejection.class,()->run(tool().put("entrypoint","/bin/sh"),prompt(),doc()));}
 @Test void absentImplementationDeclarationRejected()throws Exception{var t=tool();t.remove("implementation_id");assertThrows(SchemaRejection.class,()->run(t,prompt(),doc()));}
 @Test void toolsCannotBeEnabled()throws Exception{assertThrows(SchemaRejection.class,()->run(tool().put("tool_mode","ENABLED"),prompt(),doc()));}
 @Test void upstreamCannotBeIgnored()throws Exception{assertThrows(SchemaRejection.class,()->run(tool().put("upstream_mode","OPTIONAL"),prompt(),doc()));}
 @Test void noUndeclaredContextMode()throws Exception{assertThrows(SchemaRejection.class,()->run(tool().put("context_mode","PROFESSIONAL_PIPELINE"),prompt(),doc()));}
 @Test void schemaHashMustActuallyBePublished()throws Exception{var t=tool();((ObjectNode)t.path("input_schema")).put("schema_sha256",hash("invented"));assertThrows(TenantAccessException.class,()->run(t,prompt(),doc()));}
 @Test void unknownPromptSchemaRejected()throws Exception{var t=tool();((ObjectNode)t.path("prompt_package_schema")).put("schema_ref","urn:fake:prompt");assertThrows(TenantAccessException.class,()->run(t,prompt(),doc()));}
 @Test void exact088InputOutputBindingMandatory()throws Exception{var b=binding();var wrong=new FormalEvaluationContextProtocol.Node(b.nodeKind(),b.role(),b.prompt(),b.contextAssembler(),new FormalEvaluationContextProtocol.Schema("urn:wrong",b.inputSchema().schemaSha256()),b.outputSchema());assertThrows(TenantAccessException.class,()->compiler.compile(bytes(tool()),bytes(prompt()),doc(),planning(),wrong));}
 @Test void promptCannotSupplyUserOrToolMessages()throws Exception{assertThrows(SchemaRejection.class,()->run(tool(),prompt().put("user_content","forged"),doc()));}
 @Test void emptyPromptRejected()throws Exception{var p=prompt();p.putArray("system_messages");assertThrows(SchemaRejection.class,()->run(tool(),p,doc()));}
 @Test void nulPromptRejected()throws Exception{var p=prompt();p.putArray("system_messages").add("\0bad");assertThrows(TenantAccessException.class,()->run(tool(),p,doc()));}
 @Test void expectedAnswerNotAcceptedAsCompilerInput()throws Exception{assertThrows(SchemaRejection.class,()->run(tool(),prompt(),doc().put("expected_ref",id(99))));}
 @Test void documentSchemaCannotBecomeExactInputByRename()throws Exception{var d=json.object();d.putArray("messages");d.putArray("tools");assertThrows(SchemaRejection.class,()->run(tool(),prompt(),d));}
 @Test void noncanonicalOriginalPackagesRejected()throws Exception{assertThrows(TenantAccessException.class,()->compiler.compile((" "+json.canonical(tool())).getBytes(StandardCharsets.UTF_8),bytes(prompt()),doc(),planning(),binding()));}
 @Test void duplicateJsonKeysRejected()throws Exception{var raw=json.canonical(prompt()).replace("\"schema_version\":\"1.0.0\"","\"schema_version\":\"1.0.0\",\"schema_version\":\"1.0.0\"").getBytes(StandardCharsets.UTF_8);assertThrows(SchemaRejection.class,()->compiler.compile(bytes(tool()),raw,doc(),planning(),binding()));}
 @Test void malformedUtf8AndOversizedOriginalRejected()throws Exception{assertThrows(SchemaRejection.class,()->compiler.compile(new byte[]{(byte)0xc0,(byte)0xaf},bytes(prompt()),doc(),planning(),binding()));assertThrows(SchemaRejection.class,()->compiler.compile(new byte[2097153],bytes(prompt()),doc(),planning(),binding()));}
 @Test void actual079RequiredFieldsPreservedAndValidated()throws Exception{var d=doc();d.remove("language");assertThrows(SchemaRejection.class,()->run(tool(),prompt(),d));}
 @Test void outputOverflowDoesNotTruncateEvidence()throws Exception{var d=doc();var a=d.putArray("sections");for(int n=0;n<64;n++)a.addObject().put("section_id","s"+n).put("title","").put("text","中".repeat(32768));assertEquals(ErrorCode.CONTEXT_LIMIT,assertThrows(TenantAccessException.class,()->run(tool(),prompt(),d)).code());}
 @Test void allAuthorityProofConstructorsArePrivate(){for(var type:List.of(FormalEvaluationPlanningInputPreparation.Capture.class,FormalEvaluationPlanningInputPreparation.PreparedExactInput.class,FormalEvaluationContextPackages.Read.class))for(var c:type.getDeclaredConstructors())assertTrue(java.lang.reflect.Modifier.isPrivate(c.getModifiers()));}
 @Test void upstreamNodesCannotUseDocumentOnlyCompiler()throws Exception{var b=binding();for(String kind:List.of("N02","N03","N04","N05","N06","N07")){var n=new FormalEvaluationContextProtocol.Node(kind,b.role(),b.prompt(),b.contextAssembler(),b.inputSchema(),b.outputSchema());assertEquals(ErrorCode.DEPENDENCY_UNAVAILABLE,assertThrows(TenantAccessException.class,()->compiler.compile(bytes(tool()),bytes(prompt()),doc(),planning(),n)).code());}}
 @Test void realFixtureTokenizerConsumesActualCompiledBytes()throws Exception{var compiled=run(tool(),prompt(),doc());Path p=Files.createTempFile("evaluation-context-tokenizer-",".py");try{Files.writeString(p,"#!/usr/bin/python3\nimport sys,json\nv=json.load(sys.stdin)\nprint(json.dumps(dict(schema_version='1.0.0',tokenizer_version=v['tokenizer_version'],input_sha256=v['input_sha256'],token_count='3',complete=True)))\n");Files.setPosixFilePermissions(p,java.nio.file.attribute.PosixFilePermissions.fromString("rwx------"));String sha=org.apache.commons.codec.digest.DigestUtils.sha256Hex(Files.readAllBytes(p));var runner=new FormalTokenizerRunner(new FormalTokenizerRunner.Configuration(true,p,sha,id(91),2097152,2048,java.time.Duration.ofSeconds(2)));var result=runner.count(compiled.bytes(),id(91),sha,()->false);assertEquals(compiled.sha256(),result.inputSha256());assertEquals(sha,result.executableSha256());assertEquals(id(91),result.tokenizerVersion());assertEquals("3",result.tokenCount().toString());}finally{Files.deleteIfExists(p);}}
}
